  function ensureClientButton(){clientStyles();const nav=navRoot();if(!nav)return;const buttons=[...nav.querySelectorAll('button')],dashboard=nav.querySelector('[data-pp-dashboard-root="1"]'),finance=buttons.find(x=>norm(x.textContent).startsWith('financeiro')),systemLabel=[...nav.querySelectorAll('.nav-label,small')].find(x=>norm(x.textContent)==='sistema');let anchor=dashboard?.nextSibling||finance||systemLabel||null;let b=nav.querySelector('[data-pp-client-hub="1"]');if(!b){b=document.createElement('button');b.type='button';b.dataset.ppClientHub='1';b.innerHTML='<span>◉</span><span>Cliente</span><span class="pp-client-chevron">›</span>'}b.className=String(finance?.className||b.className||'');b.classList.remove('active');b.classList.add('pp-client-hub-button');b.setAttribute('aria-haspopup','menu');b.setAttribute('aria-expanded',clientPopup&&!clientPopup.hidden?'true':'false');b.onmouseenter=showClientPopup;b.onmouseleave=()=>clientTimer=setTimeout(closeClientPopup,150);b.onclick=e=>{e.preventDefault();e.stopPropagation();clientPopup&&!clientPopup.hidden?closeClientPopup():showClientPopup()};anchor=dashboard?.nextSibling||finance||systemLabel||null;if(anchor&&anchor!==b&&b.nextSibling!==anchor)nav.insertBefore(b,anchor);else if(!anchor&&!b.isConnected)nav.appendChild(b);clientButton=b;buildClientPopup()}
